INSERT INTO jobs (company_id, recruiter_id, title, description, responsibilities, required_skills, qualifications, location, salary_min, salary_max, job_type, experience_level, work_mode, deadline, status, is_demo, created_at, updated_at) VALUES
((SELECT id FROM companies WHERE name = 'Vertex Analytics Labs' AND is_demo = 1 LIMIT 1), @rec, 'Artificial Intelligence Engineer', 'Design and ship AI features such as semantic search and document understanding for enterprise clients. You will work closely with product managers and data engineers to move models from notebooks to production.', 'Build and evaluate machine learning and language model based features\nCreate reliable data and evaluation pipelines\nDeploy models as secure and monitored services\nDocument experiments and share findings with the team', 'Python, PyTorch, NLP, Machine Learning, REST APIs, Docker', 'B.E./B.Tech or M.Tech in Computer Science, AI or a related field\n2 to 5 years of experience building ML systems', 'Bengaluru, Karnataka', 1800000, 3000000, 'FULL_TIME', 'MID', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 45 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 2 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Vertex Analytics Labs' AND is_demo = 1 LIMIT 1), @rec, 'Machine Learning Engineer', 'Own the training and serving workflow for demand forecasting and recommendation models. The role is fully remote within India with occasional team meetups.', 'Train, tune and validate forecasting models\nAutomate retraining and model monitoring\nWork with data engineers on feature pipelines\nReview code and mentor junior engineers', 'Python, Scikit-learn, TensorFlow, SQL, MLOps, Git', 'Bachelor degree in a quantitative field\n3+ years of applied machine learning experience', 'Remote (India)', 1500000, 2800000, 'FULL_TIME', 'MID', 'REMOTE', DATE_ADD(CURDATE(), INTERVAL 50 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 3 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Orbit Fintech' AND is_demo = 1 LIMIT 1), @rec, 'Data Scientist', 'Use transaction and repayment data to build credit risk and fraud detection models. You will present insights to business and risk teams.', 'Develop risk scoring and fraud models\nRun experiments and A/B tests\nPrepare dashboards and clear written analysis\nCollaborate with engineering to deploy models', 'Python, Statistics, SQL, Pandas, Machine Learning, Data Visualization', 'Degree in Statistics, Mathematics, Computer Science or similar\n2 to 4 years of experience in analytics or data science', 'Mumbai, Maharashtra', 1400000, 2400000, 'FULL_TIME', 'MID', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 40 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 4 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Lumen Retail Solutions' AND is_demo = 1 LIMIT 1), @rec, 'Data Analyst', 'Turn order, inventory and customer data into weekly insights for the operations team. Ideal for someone with strong SQL and Excel skills who enjoys storytelling with data.', 'Write SQL queries and maintain reporting dashboards\nTrack sales, delivery and return metrics\nFlag trends and anomalies to operations managers\nClean and validate data from multiple sources', 'SQL, Excel, Power BI, Data Analysis, Python', 'Bachelor degree in any discipline with strong analytical skills\n0 to 2 years of experience', 'Gurugram, Haryana', 500000, 900000, 'FULL_TIME', 'JUNIOR', 'ONSITE', DATE_ADD(CURDATE(), INTERVAL 35 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 5 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'BlueRiver Systems' AND is_demo = 1 LIMIT 1), @rec, 'Java Backend Developer', 'Build secure, scalable REST services for banking customers using Spring Boot and MySQL. You will take features from design through production support.', 'Develop and maintain Spring Boot microservices\nDesign relational database schemas and optimise queries\nWrite unit and integration tests\nParticipate in code reviews and on-call rotation', 'Java 17, Spring Boot, Spring Security, MySQL, REST APIs, JUnit', 'B.E./B.Tech in Computer Science or equivalent\n3+ years of backend development experience', 'Pune, Maharashtra', 1000000, 1800000, 'FULL_TIME', 'MID', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 42 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 6 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Pixelforge Studio' AND is_demo = 1 LIMIT 1), @rec, 'React Frontend Developer', 'Create polished, accessible interfaces for client web applications with React. You will work directly with designers to turn prototypes into production code.', 'Build reusable React components\nImplement responsive and accessible layouts\nIntegrate REST APIs and handle loading and error states\nWrite component tests and fix browser issues', 'React, JavaScript, HTML5, CSS3, Git, REST APIs', 'Bachelor degree or equivalent practical experience\n1 to 3 years of React experience with a portfolio', 'Mumbai, Maharashtra', 600000, 1200000, 'FULL_TIME', 'JUNIOR', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 38 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 1 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'CodeCrest Technologies' AND is_demo = 1 LIMIT 1), @rec, 'Full-Stack Developer', 'Work on end-to-end features for customer portals, from React screens to Spring Boot services and MySQL tables. You will join a small agile team.', 'Develop UI and API features end to end\nModel data and write efficient queries\nTroubleshoot production issues\nEstimate and plan work with the team', 'React, Java, Spring Boot, MySQL, REST APIs, Git', 'B.E./B.Tech in Computer Science or similar\n2 to 4 years of full-stack experience', 'Hyderabad, Telangana', 900000, 1700000, 'FULL_TIME', 'MID', 'ONSITE', DATE_ADD(CURDATE(), INTERVAL 48 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 7 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'CodeCrest Technologies' AND is_demo = 1 LIMIT 1), @rec, 'Software Engineer', 'Entry-level engineering role with structured training in Java, databases and testing. You will pair with senior engineers on real customer modules.', 'Complete the onboarding and training programme\nImplement small features and bug fixes\nWrite unit tests for new code\nLearn code review and deployment practices', 'Java, SQL, Data Structures, Problem Solving, Git', 'B.E./B.Tech or MCA graduating in 2025 or 2026\nGood understanding of programming fundamentals', 'Hyderabad, Telangana', 450000, 700000, 'FULL_TIME', 'FRESHER', 'ONSITE', DATE_ADD(CURDATE(), INTERVAL 60 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 8 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Nimbus Cloudworks' AND is_demo = 1 LIMIT 1), @rec, 'DevOps Engineer', 'Maintain CI/CD pipelines and container platforms for product teams. You will improve release speed, reliability and observability.', 'Build and maintain CI/CD pipelines\nManage Kubernetes clusters and Docker images\nAutomate infrastructure with Terraform\nSet up monitoring, logging and alerting', 'Docker, Kubernetes, Jenkins, Terraform, Linux, AWS, Git', 'Degree in Computer Science or equivalent experience\n3+ years in DevOps or site reliability roles', 'Hyderabad, Telangana', 1200000, 2200000, 'FULL_TIME', 'MID', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 44 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 2 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Helix Cyber Defense' AND is_demo = 1 LIMIT 1), @rec, 'Cybersecurity Analyst', 'Monitor security alerts, investigate incidents and support vulnerability assessments for client environments in a security operations centre.', 'Triage and investigate security alerts\nPerform vulnerability scans and report findings\nMaintain incident response runbooks\nRecommend practical security improvements', 'SIEM, Network Security, Vulnerability Assessment, Linux, Incident Response', 'Bachelor degree in IT or related field\nSecurity certification such as CEH or Security+ is a plus', 'Gurugram, Haryana', 700000, 1300000, 'FULL_TIME', 'JUNIOR', 'ONSITE', DATE_ADD(CURDATE(), INTERVAL 36 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 9 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Nimbus Cloudworks' AND is_demo = 1 LIMIT 1), @rec, 'Cloud Engineer', 'Design secure and cost-efficient AWS and Azure environments for client workloads. You will lead architecture reviews and migration projects.', 'Design cloud architectures and landing zones\nLead migrations from on-premise to cloud\nDefine security and cost controls\nMentor engineers and write technical documentation', 'AWS, Azure, Terraform, Networking, IAM, Python, Cost Optimisation', '6+ years in infrastructure or cloud engineering\nProfessional cloud certification preferred', 'Remote (India)', 2000000, 3500000, 'FULL_TIME', 'SENIOR', 'REMOTE', DATE_ADD(CURDATE(), INTERVAL 55 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 10 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Pixelforge Studio' AND is_demo = 1 LIMIT 1), @rec, 'UI/UX Designer', 'Design intuitive web and mobile experiences, from user research to high-fidelity prototypes, and hand off clean specifications to developers.', 'Conduct user research and usability tests\nCreate wireframes, flows and prototypes\nMaintain a shared design system\nWork with developers during implementation', 'Figma, User Research, Wireframing, Prototyping, Design Systems', 'Degree or diploma in Design, HCI or related field\nPortfolio with at least three case studies', 'Mumbai, Maharashtra', 500000, 1000000, 'FULL_TIME', 'JUNIOR', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 33 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 11 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Orbit Fintech' AND is_demo = 1 LIMIT 1), @rec, 'Product Manager', 'Own the roadmap for merchant lending products. You will balance customer needs, compliance and business goals while working with engineering and design.', 'Define product vision and roadmap\nWrite clear requirements and prioritise the backlog\nAnalyse funnel metrics and customer feedback\nCoordinate launches with business and compliance teams', 'Product Strategy, Roadmapping, Analytics, Stakeholder Management, SQL', '5+ years of product management experience\nExperience in fintech or lending is preferred', 'Mumbai, Maharashtra', 2200000, 3800000, 'FULL_TIME', 'SENIOR', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 52 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 12 DAY), NOW()),
((SELECT id FROM companies WHERE name = 'Zenith Health Tech' AND is_demo = 1 LIMIT 1), @rec, 'Business Analyst', 'Translate hospital workflow needs into clear requirements for engineering teams, and support user acceptance testing and releases.', 'Gather and document business requirements\nCreate user stories, process maps and acceptance criteria\nCoordinate user acceptance testing\nSupport customers during rollout', 'Requirements Analysis, SQL, Jira, Process Modelling, Communication', 'Bachelor degree in Engineering, IT or Business\n2 to 5 years of business analysis experience', 'Chennai, Tamil Nadu', 800000, 1500000, 'FULL_TIME', 'MID', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 41 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 13 DAY), NOW()),
