((SELECT id FROM companies WHERE name = 'GreenLeaf Commerce' AND is_demo = 1 LIMIT 1), @rec, 'Digital Marketing Specialist', 'Plan and run paid and organic campaigns for consumer brands, track results and report on growth metrics.', 'Run search and social media campaigns\nOptimise content for SEO\nTrack performance in analytics tools\nPrepare monthly reports for clients', 'SEO, Google Ads, Social Media Marketing, Google Analytics, Content Marketing', 'Bachelor degree in Marketing, Business or similar\n1 to 3 years of digital marketing experience', 'Chennai, Tamil Nadu', 400000, 800000, 'FULL_TIME', 'JUNIOR', 'HYBRID', DATE_ADD(CURDATE(), INTERVAL 34 DAY), 'PUBLISHED', 1, DATE_SUB(NOW(), INTERVAL 19 DAY), NOW()),
